-- Explicit capability only; no existing user's grants are expanded.
ALTER TABLE hs_data_collection_grants DROP CONSTRAINT IF EXISTS hs_data_collection_grants_capabilities_check;
ALTER TABLE hs_data_collection_grants ADD CONSTRAINT hs_data_collection_grants_capabilities_check CHECK(capabilities <@ ARRAY['view','create','edit','link','import','export','bulk','archive','delete','restore','merge','schema','manage-views','history','restore-values','manage-templates']::text[]);
CREATE TABLE IF NOT EXISTS hs_data_template_catalogues(tenant_id uuid NOT NULL,collection text NOT NULL,revision integer NOT NULL DEFAULT 1,PRIMARY KEY(tenant_id,collection),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_record_templates(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,collection text NOT NULL,name text NOT NULL,name_search text GENERATED ALWAYS AS(lower(name)) STORED,version integer NOT NULL DEFAULT 1,deprecated boolean NOT NULL DEFAULT false,defaults jsonb NOT NULL,created_by text NOT NULL REFERENCES hs_users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,collection,name_search),FOREIGN KEY(tenant_id,collection) REFERENCES hs_data_collections(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_record_template_versions(tenant_id uuid NOT NULL,template_id uuid NOT NULL,version integer NOT NULL,name text NOT NULL,deprecated boolean NOT NULL,defaults jsonb NOT NULL,schema_version integer NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,template_id,version),FOREIGN KEY(tenant_id,template_id) REFERENCES hs_data_record_templates(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_record_template_operations(tenant_id uuid NOT NULL,actor_id text NOT NULL,operation_id uuid NOT NULL,request_hash text NOT NULL,template_id uuid NOT NULL,applied_version integer NOT NULL,PRIMARY KEY(tenant_id,actor_id,operation_id),FOREIGN KEY(tenant_id,template_id) REFERENCES hs_data_record_templates(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_record_template_previews(id uuid PRIMARY KEY,tenant_id uuid NOT NULL,workspace_id text NOT NULL REFERENCES hs_workspaces(id),actor_id text NOT NULL REFERENCES hs_users(id),template_id uuid NOT NULL,template_version integer NOT NULL,schema_version integer NOT NULL,policy_version integer NOT NULL,authority_revision text NOT NULL,input_hash text NOT NULL,review_hash text NOT NULL,expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '10 minutes',FOREIGN KEY(tenant_id,template_id) REFERENCES hs_data_record_templates(tenant_id,id));
CREATE TABLE IF NOT EXISTS hs_data_record_template_origins(tenant_id uuid NOT NULL,record_id uuid NOT NULL,template_id uuid NOT NULL,template_version integer NOT NULL,actor_id text NOT NULL REFERENCES hs_users(id),operation_id uuid NOT NULL,input_hash text NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,record_id),UNIQUE(tenant_id,actor_id,operation_id),FOREIGN KEY(tenant_id,record_id) REFERENCES hs_data_records(tenant_id,id),FOREIGN KEY(tenant_id,template_id,template_version) REFERENCES hs_data_record_template_versions(tenant_id,template_id,version));
DROP TRIGGER IF EXISTS hs_data_record_template_versions_immutable ON hs_data_record_template_versions;
CREATE TRIGGER hs_data_record_template_versions_immutable BEFORE UPDATE OR DELETE ON hs_data_record_template_versions FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
DROP TRIGGER IF EXISTS hs_data_record_template_origins_immutable ON hs_data_record_template_origins;
CREATE TRIGGER hs_data_record_template_origins_immutable BEFORE UPDATE OR DELETE ON hs_data_record_template_origins FOR EACH ROW EXECUTE FUNCTION hs_data_history_immutable();
CREATE OR REPLACE FUNCTION hs_data_record_template_identity_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.id<>OLD.id OR NEW.tenant_id<>OLD.tenant_id OR NEW.collection<>OLD.collection OR NEW.created_by<>OLD.created_by OR NEW.created_at<>OLD.created_at THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='Template identity and collection are immutable'; END IF;RETURN NEW;END $$;
DROP TRIGGER IF EXISTS hs_data_record_template_identity_guard ON hs_data_record_templates;
CREATE TRIGGER hs_data_record_template_identity_guard BEFORE UPDATE ON hs_data_record_templates FOR EACH ROW EXECUTE FUNCTION hs_data_record_template_identity_guard();
ALTER TABLE hs_data_schema_dependencies DROP CONSTRAINT IF EXISTS hs_data_schema_dependencies_kind_check;
ALTER TABLE hs_data_schema_dependencies ADD CONSTRAINT hs_data_schema_dependencies_kind_check CHECK(kind IN ('view','import-mapping','integration','reference-policy','template'));
ALTER TABLE hs_data_schema_dependencies ADD COLUMN IF NOT EXISTS template_id uuid REFERENCES hs_data_record_templates(id);
